-- Real NYC daily weather (Open-Meteo historical archive, free, no key, CC BY 4.0) as a Zetaris REST table.
CREATE LIGHTNING DATABASE NYC_WEATHER_REST DESCRIBE BY "Open-Meteo historical daily weather for New York City"
CREATE LIGHTNING REST TABLE daily_raw FROM NYC_WEATHER_REST REQUEST(endpoint "https://archive-api.open-meteo.com/v1/archive?latitude=40.7128&longitude=-74.0060&start_date=2024-07-01&end_date=2024-09-30&daily=temperature_2m_max,temperature_2m_min,precipitation_sum,rain_sum,snowfall_sum,wind_speed_10m_max,weather_code&timezone=America%2FNew_York", method "get", response_type "json", http_encoding "URLENCODED") HEADER () BODY ()
CREATE SCHEMASTORE CONTAINER investigator
CREATE SCHEMASTORE VIEW nyc_daily_weather WITH CONTAINER investigator AS SELECT CAST(d.time AS DATE) AS day, d.temperature_2m_max AS temp_max_c, d.temperature_2m_min AS temp_min_c, d.precipitation_sum AS precip_mm, d.rain_sum AS rain_mm, d.snowfall_sum AS snow_cm, d.wind_speed_10m_max AS wind_max_kmh, d.weather_code AS wmo_code FROM NYC_WEATHER_REST.daily_raw LATERAL VIEW explode(arrays_zip(daily.time, daily.temperature_2m_max, daily.temperature_2m_min, daily.precipitation_sum, daily.rain_sum, daily.snowfall_sum, daily.wind_speed_10m_max, daily.weather_code)) z AS d
